const BASE_URL = 'http://localhost:5000';

async function request(path, options = {}) {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    ...options,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(text || `Request failed: ${res.status}`);
  }

  return res.json();
}

function parseArray(value) {
  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    const trimmed = value.trim();

    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed;
    } catch (err) {
      // ignore
    }

    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
      return trimmed
        .slice(1, -1)
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean)
        .map((v) => {
          const n = Number(v);
          return Number.isNaN(n) ? v : n;
        });
    }

    if (trimmed.includes('->')) {
      return trimmed
        .split('->')
        .map((v) => v.trim())
        .filter(Boolean)
        .map((v) => {
          const n = Number(v);
          return Number.isNaN(n) ? v : n;
        });
    }

    if (trimmed.includes(',')) {
      return trimmed
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean)
        .map((v) => {
          const n = Number(v);
          return Number.isNaN(n) ? v : n;
        });
    }
  }

  return [];
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeCycleItem(item, index = 0) {
  const cycle = parseArray(item?.cycle);
  const tradePath = parseArray(item?.trade_path || item?.tradepath);
  const culprits = parseArray(item?.culprits);
  const allCycles = Array.isArray(item?.all_cycles)
    ? item.all_cycles.map(parseArray)
    : [];
  const allTradePaths = Array.isArray(item?.all_trade_paths)
    ? item.all_trade_paths.map(parseArray)
    : [];
  const rootTradeIds = parseArray(item?.root_trade_ids);

  return {
    cycle_id: item?.cycle_id || `cycle-${item?.stock_id || 'x'}-${index}`,
    stock_id: item?.stock_id,
    symbol: item?.symbol || `#${item?.stock_id ?? '—'}`,
    cycle,
    trade_path: tradePath,
    culprits: culprits.length ? culprits : cycle.slice(0, -1),
    all_cycles: allCycles,
    all_trade_paths: allTradePaths,
    root_trade_ids: rootTradeIds,
    max_depth: toNumber(item?.max_depth ?? item?.depth),
    confidence: toNumber(item?.confidence),
    occurrences: toNumber(item?.occurrences, 1),
    fastest_loop_minutes: toNumber(item?.fastest_loop_minutes),
    avg_loop_minutes: toNumber(item?.avg_loop_minutes),
    first_seen_at: item?.first_seen_at || item?.detected_at || null,
    last_seen_at: item?.last_seen_at || item?.detected_at || null,
    explanation: item?.explanation || '',
  };
}

function normalizeRiskLog(log) {
  return {
    ...log,
    risk_id: log?.risk_id ?? log?.riskid,
    trade_id: log?.trade_id ?? log?.tradeid,
    risk_score: toNumber(log?.risk_score ?? log?.riskscore),
    risk_label: log?.risk_label || log?.risklabel || null,
    stock_id: log?.stock_id ?? log?.stockid,
    symbol: log?.symbol || null,
    seller_id: log?.seller_id ?? log?.sellerid,
    seller_name: log?.seller_name ?? log?.sellername,
    buyer_id: log?.buyer_id ?? log?.buyerid,
    buyer_name: log?.buyer_name ?? log?.buyername,
    price: toNumber(log?.price),
    quantity: toNumber(log?.quantity),
    detected_at: log?.detected_at ?? log?.detectedat ?? null,
    trade_timestamp: log?.trade_timestamp ?? log?.timestamp ?? null,
  };
}

export const api = {
  fetchStats: async () => {
    const data = await request('/api/stats');
    return {
      total_trades: toNumber(data?.total_trades ?? data?.totaltrades),
      total_traders: toNumber(data?.total_traders ?? data?.totaltraders),
      total_risk_logs: toNumber(data?.total_risk_logs ?? data?.totalrisklogs),
      fraud_rings_detected: toNumber(data?.fraud_rings_detected ?? data?.fraudringsdetected),
      high_risk_traders: toNumber(data?.high_risk_traders ?? data?.highrisktraders),
      monitored_traders: toNumber(data?.monitored_traders ?? data?.monitoredtraders ?? data?.total_traders),
      high_confidence_rings: toNumber(data?.high_confidence_rings),
      recent_risk_events: toNumber(data?.recent_risk_events),
      avg_trust_score: toNumber(data?.avg_trust_score),
    };
  },

  fetchFraudCycles: async () => {
    const data = await request('/api/fraud/cycles');
    const rows = normalizeArrayPayload(data);
    return rows.map(normalizeCycleItem);
  },

  fetchFraudLogs: async () => {
    const data = await request('/api/fraud/logs');
    const rows = normalizeArrayPayload(data);
    return rows.map(normalizeRiskLog);
  },

  fetchRiskLogs: async () => {
    const data = await request('/api/fraud/logs');
    const rows = normalizeArrayPayload(data);
    return rows.map(normalizeRiskLog);
  },

  fetchTraders: async () => {
    const data = await request('/api/traders');
    return normalizeArrayPayload(data);
  },

  fetchTrades: async (page = 1, limit = 50) => {
    const data = await request(`/api/trades?page=${page}&limit=${limit}`);
    return normalizeArrayPayload(data);
  },
};

export function normalizeArrayPayload(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.cycles)) return payload.cycles;
  if (Array.isArray(payload?.logs)) return payload.logs;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.rows)) return payload.rows;
  if (Array.isArray(payload?.trades)) return payload.trades;
  return [];
}

export function normalizeTrades(trades, logs) {
  if (!Array.isArray(trades)) return [];

  const riskByTrade = new Map(
    (Array.isArray(logs) ? logs : []).map((log) => [
      Number(log.trade_id ?? log.tradeid),
      normalizeRiskLog(log),
    ])
  );

  return trades.map((trade) => {
    const tradeId = Number(trade.trade_id ?? trade.tradeid);
    const linkedRisk = riskByTrade.get(tradeId);

    return {
      ...trade,
      trade_id: tradeId,
      stock_id: trade.stock_id ?? trade.stockid,
      seller_id: trade.seller_id ?? trade.sellerid,
      buyer_id: trade.buyer_id ?? trade.buyerid,
      seller_name: trade.seller_name ?? trade.sellername,
      buyer_name: trade.buyer_name ?? trade.buyername,
      symbol: trade.symbol || `#${trade.stock_id ?? trade.stockid ?? '—'}`,
      price: toNumber(trade.price),
      quantity: toNumber(trade.quantity),
      timestamp: trade.timestamp || null,
      risk_score: linkedRisk?.risk_score ?? 0,
      risk_label: linkedRisk?.risk_label ?? null,
      risk_reason: linkedRisk?.reason ?? null,
      detected_at: linkedRisk?.detected_at ?? null,
    };
  });
}

export function badgeClass(score) {
  const s = Number(score || 0);
  if (s >= 70) return 'badge badge-high';
  if (s >= 40) return 'badge badge-medium';
  return 'badge badge-low';
}

export function parseCycleArray(value) {
  return parseArray(value);
}
